"""Fetch a feed over HTTP, retrying server errors and network failures."""

import http.client
import urllib.error
import urllib.request
from collections.abc import Callable
from dataclasses import dataclass
from http import HTTPStatus

from feedcheck.config import RetryPolicy

FIRST_ATTEMPT = 0


class FeedUnreachable(Exception):
    """The feed's server did not answer within the attempts allowed."""

    def __init__(self, url: str, reason: str) -> None:
        super().__init__(f"{url}: {reason}")
        self.reason = reason


@dataclass(frozen=True)
class Response:
    status: int
    body: bytes
    attempts: int


class _KeepErrorStatus(urllib.request.HTTPErrorProcessor):
    """Hand 4xx and 5xx responses back as responses; keep following redirects."""

    def http_response(self, request, response):  # noqa: ANN001 - urllib handler signature
        if HTTPStatus.MULTIPLE_CHOICES <= response.status < HTTPStatus.BAD_REQUEST:
            return super().http_response(request, response)
        return response

    https_response = http_response


_OPENER = urllib.request.build_opener(_KeepErrorStatus)


def is_server_error(status: int) -> bool:
    return status >= HTTPStatus.INTERNAL_SERVER_ERROR


def fetch(url: str, retry: RetryPolicy, sleep: Callable[[float], None]) -> Response:
    """Fetch ``url``, retrying a 5xx answer or no answer up to ``retry.attempts`` times.

    Returns the last response, which may still be a 5xx when attempts ran out.
    Raises FeedUnreachable when the last attempt got no answer at all.
    """
    last_attempt = retry.attempts - 1
    for attempt in range(retry.attempts):
        if attempt > FIRST_ATTEMPT:
            sleep(retry.retry_delay_seconds * attempt)
        try:
            status, body = _fetch_once(url, retry.timeout_seconds)
        except FeedUnreachable:
            if attempt == last_attempt:
                raise
            continue
        if attempt == last_attempt or not is_server_error(status):
            return Response(status=status, body=body, attempts=attempt + 1)
    raise AssertionError("the retry loop always returns or raises on its last attempt")


def _fetch_once(url: str, timeout_seconds: float) -> tuple[int, bytes]:
    # Boundary (declared in .shockharness.toml): one network exchange.
    try:
        result = _download(url, timeout_seconds)
    except (urllib.error.URLError, TimeoutError, ConnectionError, http.client.HTTPException) as exc:
        raise FeedUnreachable(url, _describe(exc)) from exc
    return result


def _download(url: str, timeout_seconds: float) -> tuple[int, bytes]:
    request = urllib.request.Request(url, headers={"Accept": "application/json"})
    with _OPENER.open(request, timeout=timeout_seconds) as response:
        return response.status, response.read()


def _describe(exc: BaseException) -> str:
    if isinstance(exc, urllib.error.URLError):
        return f"no answer: {exc.reason}"
    if isinstance(exc, TimeoutError):
        return "no answer: timed out"
    return f"no answer: {type(exc).__name__}: {exc}"
