"""Check every configured feed and build the report."""

import time
from collections.abc import Callable
from dataclasses import dataclass
from datetime import UTC, datetime

from feedcheck.config import Config, Feed
from feedcheck.health import Status, Verdict, judge
from feedcheck.http_fetch import fetch


@dataclass(frozen=True)
class FeedResult:
    feed: Feed
    verdict: Verdict
    duration_seconds: float


@dataclass(frozen=True)
class Report:
    checked_at: datetime
    results: tuple[FeedResult, ...]

    @property
    def all_healthy(self) -> bool:
        return all(result.verdict.status is Status.HEALTHY for result in self.results)

    def to_json(self) -> dict[str, object]:
        return {
            "checked_at": self.checked_at.isoformat(),
            "all_healthy": self.all_healthy,
            "feeds": [
                {
                    "name": result.feed.name,
                    "url": result.feed.url,
                    "status": str(result.verdict.status),
                    "reason": result.verdict.reason,
                    "items": result.verdict.item_count,
                    "duration_seconds": result.duration_seconds,
                }
                for result in self.results
            ],
        }


def check_all(config: Config, sleep: Callable[[float], None]) -> Report:
    checked_at = datetime.now(UTC)
    results = tuple(check_feed(feed, config, sleep) for feed in config.feeds)
    if len(results) != len(config.feeds):
        raise AssertionError("the report must list every configured feed")
    return Report(checked_at=checked_at, results=results)


def check_feed(feed: Feed, config: Config, sleep: Callable[[float], None]) -> FeedResult:
    started = time.monotonic()
    outcome = fetch(feed.url, config.retry, sleep)
    verdict = judge(feed, outcome, datetime.now(UTC))
    return FeedResult(feed=feed, verdict=verdict, duration_seconds=time.monotonic() - started)
EOF
cat > feedcheck/cli.py <<'EOF'
"""Command-line entry point: ``feedcheck --config feeds.toml --output report.json``."""

import argparse
import json
import sys
import time
from collections.abc import Sequence
from pathlib import Path

from feedcheck.checker import check_all
from feedcheck.config import ConfigError, load_config

EXIT_ALL_HEALTHY = 0
EXIT_NOT_ALL_HEALTHY = 1
REPORT_INDENT = "  "


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="feedcheck", description="Check whether JSON feeds are healthy.")
    parser.add_argument("--config", required=True, type=Path, help="TOML file listing the feeds")
    parser.add_argument("--output", required=True, type=Path, help="where to write the JSON report")
    return parser


def main(argv: Sequence[str]) -> int:
    """Run the check; returns the exit code. A bad config raises SystemExit with a message."""
    arguments = build_parser().parse_args(argv)
    config = _load_or_exit(arguments.config)
    report = check_all(config, time.sleep)
    text = json.dumps(report.to_json(), indent=REPORT_INDENT)
    arguments.output.write_text(text + "\n", encoding="utf-8")
    if report.all_healthy:
        return EXIT_ALL_HEALTHY
    return EXIT_NOT_ALL_HEALTHY


def _load_or_exit(path: Path):  # -> Config
    try:
        return load_config(path)
    except ConfigError as exc:
        raise SystemExit(f"feedcheck: {exc}") from exc


def run() -> None:
    sys.exit(main(sys.argv[1:]))
EOF
